6	/**
7	 * Link honesty for supplied inputs.
8	 *
9	 * Yuku resolves relative specifiers against the supplied file set; every other
10	 * specifier is left unresolved. A build-tool alias ('containers/App/actions'
11	 * under webpack `resolve.modules`) is therefore indistinguishable from a real
12	 * package import by shape alone, and the importing file silently fails to join
13	 * the module graph: traversal queries neither answer from it nor name it.
14	 *
15	 * The only evidence available to the engine — without a second resolver, a
16	 * config reader, or the filesystem — is the supplied path set itself. So a
17	 * failed specifier that *names a supplied input* (matches some supplied path,
18	 * modulo extension, `/index`, and leading directories) is treated as a link
19	 * that should have been made and was not: reason 'unlinked-input'. A failed
20	 * specifier that names nothing in the supplied set is a recognized external or
21	 * builtin boundary and keeps its existing reason.
22	 *
23	 * The rule errs toward naming: a package specifier that happens to collide
24	 * with a supplied path is reported rather than assumed external.
25	 */
26	
27	const nodeBuiltins = new Set([...builtinModules, ...builtinModules.map((name) => `node:${name}`)]);
28	
29	const moduleExtensions = ['.tsx', '.ts', '.jsx', '.js', '.mts', '.mjs', '.cts', '.cjs'] as const;
30	
31	function stripExtension(path: string): string {
32		const extension = moduleExtensions.find((candidate) => path.endsWith(candidate));
33		return extension === undefined ? path : path.slice(0, -extension.length);
34	}
35	
36	function pathForms(path: string): string[] {
37		const forms = new Set<string>([path]);
38		const base = stripExtension(path);
39		forms.add(base);
40		if (base.endsWith('/index')) forms.add(base.slice(0, -'/index'.length));
41		return [...forms].filter((form) => form.length > 0);
42	}
43	
44	function segmentSuffixes(path: string): string[] {
45		const parts = path.split('/');
46		return parts
47			.map((_, index) => parts.slice(index).join('/'))
48			.filter((suffix) => suffix.length > 0);
49	}
50	
51	const indexCache = new WeakMap<Analyzer, { key: string; keys: ReadonlySet<string> }>();
52	
53	/**
54	 * Every name under which a supplied input could plausibly be requested: each
55	 * supplied path, without its extension, without a trailing '/index', and with
56	 * any number of leading directory segments dropped (alias roots are unknown).
57	 */
58	export function suppliedInputIndex(analyzer: Analyzer): ReadonlySet<string> {
59		const key = [...analyzer.modules.keys()].sort().join('\u0000');
60		const cached = indexCache.get(analyzer);
61		if (cached !== undefined && cached.key === key) return cached.keys;
62		const keys = new Set<string>();
63		for (const path of analyzer.modules.keys())
64			for (const form of pathForms(path))
65				for (const suffix of segmentSuffixes(form)) keys.add(suffix);
66		indexCache.set(analyzer, { key, keys });
67		return keys;
68	}
