71		const withoutLoaders = specifier.slice(specifier.lastIndexOf('!') + 1);
72		const withoutQuery = withoutLoaders.split('?')[0]?.split('#')[0] ?? '';
73		return withoutQuery.replace(/\/+$/, '').replace(/^\/+/, '');
