90		if (nodeBuiltins.has(specifier)) return 'builtin-module-boundary';
91		if (namesSuppliedInput(specifier, keys)) return 'unlinked-input';
92		return specifier.startsWith('.') ? 'unresolved-specifier' : 'external-module-boundary';
