96		kind: 'import' | 'export',
97		specifier: string,
98		reason: UnresolvedReason,
99	): string {
100		const subject = kind === 'import' ? `Import '${specifier}'` : `Export from '${specifier}'`;
101		return reason === 'unlinked-input'
102			? `${subject} did not resolve, but names a supplied input; the link between these files could not be established.`
103			: `${subject} leaves the linked file set.`;
104	}
105	
106	/**
107	 * Names every supplied input outside the traversed graph whose own specifiers
108	 * failed to link to another supplied input. Such a file might belong in the
109	 * traversal and cannot be shown not to, so it is reported rather than dropped.
110	 * Modules already inside the traversed set are skipped: their boundaries are
111	 * named by the traversal's own gap collection, with identical anchors.
112	 */
113	export function unlinkedInputSites(
114		analyzer: Analyzer,
115		traversed: ReadonlySet<Module>,
116		labelPrefix = '',
117	): UnresolvedSite[] {
118		const keys = suppliedInputIndex(analyzer);
119		const sites: UnresolvedSite[] = [];
120		for (const module of analyzer.modules.values()) {
121			if (traversed.has(module)) continue;
122			for (const record of module.imports) {
123				if (record.resolvedModule !== null) continue;
124				if (boundaryReason(record.specifier, keys) !== 'unlinked-input') continue;
125				sites.push({
126					site: anchorSite(module, record.node, `${labelPrefix}import-boundary`),
127					reason: 'unlinked-input',
128					detail: boundaryDetail('import', record.specifier, 'unlinked-input'),
129				});
130			}
131			for (const record of module.exports) {
132				if (record.specifier === null || record.resolvedModule !== null) continue;
133				if (boundaryReason(record.specifier, keys) !== 'unlinked-input') continue;
134				sites.push({
135					site: anchorSite(module, record.node, `${labelPrefix}export-boundary`),
136					reason: 'unlinked-input',
137					detail: boundaryDetail('export', record.specifier, 'unlinked-input'),
138				});
139			}
140		}
141		return sites;
142	}
