1	// run-demo.mjs — must-have demonstration: scope-resolved symbol truth at repo scale.
2	//
3	// Input set (mechanical, committed content only):
4	//   git -C <markless> ls-files '*.ts' | grep '^packages/'    (635 files)
5	// Every file's source is read from the *commit* 931f0544 via `git archive`, never from the
6	// markless working tree, so a dirty checkout cannot change the answer and nothing is written
7	// to the corpus.
8	//
9	// Queries, per target binding, anchors derived by the engine only (no hand-authored anchors):
10	//   1. resolveBinding(file, name, space=value, scope=null)  -> anchor
11	//   2. referencesOf(anchor from step 1)
12	//
13	// Writes only inside docs/evidence/adoption-eval-fable-v2/demonstration/ (+ an OS temp dir for
14	// the corpus extract and the ~9 MB query documents).
15	//
16	// Usage: node docs/evidence/adoption-eval-fable-v2/demonstration/run-demo.mjs
17	
18	import { execFileSync } from 'node:child_process';
19	import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
20	import { tmpdir } from 'node:os';
21	import { dirname, join } from 'node:path';
22	import { fileURLToPath } from 'node:url';
23	
24	// P5 measures prepare + query: the clock starts before the corpus is materialised.
25	const started = process.hrtime.bigint();
26	
27	const HERE = dirname(fileURLToPath(import.meta.url));
28	const REPO = join(HERE, '..', '..', '..', '..');
29	const CLI = join(REPO, 'packages', 'cli', 'dist', 'cli.js');
30	const MARKLESS = '/Users/jacksm5pro/dev/open-source/markless';
31	const COMMIT = '931f054444a41c0527dfa77f812fa49e87df3b8f';
32	
33	const head = execFileSync('git', ['-C', MARKLESS, 'rev-parse', COMMIT], { encoding: 'utf8' }).trim();
34	
35	// --- input set -------------------------------------------------------------------------------
36	const inputPaths = execFileSync('git', ['-C', MARKLESS, 'ls-files', '*.ts'], {
37		encoding: 'utf8',
38		maxBuffer: 1 << 28,
39	})
40		.split('\n')
41		.filter((p) => p.startsWith('packages/'));
42	inputPaths.sort();
43	writeFileSync(join(HERE, 'input-files.txt'), `${inputPaths.join('\n')}\n`);
44	
45	// --- committed sources, extracted read-only out of the object database -------------------------
46	const scratch = mkdtempSync(join(tmpdir(), 'guessless-demo-'));
47	const corpus = join(scratch, 'corpus');
48	mkdirSync(corpus);
49	const tarPath = join(scratch, 'corpus.tar');
50	execFileSync('git', ['-C', MARKLESS, 'archive', COMMIT, '-o', tarPath, '--', ...inputPaths]);
51	execFileSync('tar', ['-x', '-f', tarPath, '-C', corpus]);
52	
53	const inputs = inputPaths.map((path) => ({ path, source: readFileSync(join(corpus, path), 'utf8') }));
54	const corpusBytes = inputs.reduce((n, i) => n + Buffer.byteLength(i.source, 'utf8'), 0);
55	
56	// --- queries ----------------------------------------------------------------------------------
57	const symbols = [
58		{
59			id: 'S1',
60			name: 'deserializeGraphValue',
61			file: 'packages/serializer/src/value-decode.ts',
62		},
63		{
64			id: 'S2',
65			name: 'ASYNC_BOUNDARY_ARM',
66			file: 'packages/serializer/src/async-boundary-arm.ts',
67		},
68	];
69	
70	function runQuery(id, request) {
71		const docPath = join(scratch, `${id}.query.json`);
72		writeFileSync(docPath, JSON.stringify({ inputs, request }));
73		const started = process.hrtime.bigint();
74		let stdout;
75		let stderr = '';
76		let exitCode = 0;
77		try {
78			stdout = execFileSync('node', [CLI, 'query', docPath], { encoding: 'utf8', maxBuffer: 1 << 28 });
79		} catch (error) {
80			stdout = error.stdout ?? '';
81			stderr = error.stderr ?? '';
82			exitCode = error.status ?? 1;
83		}
84		const wallMs = Number(process.hrtime.bigint() - started) / 1e6;
85		rmSync(docPath, { force: true });
86		writeFileSync(join(HERE, `${id}.receipt.json`), stdout);
87		if (stderr) process.stderr.write(`[${id}] ${stderr}`);
88		return {
89			id,
90			request,
91			receipt: JSON.parse(stdout),
92			wallMs: Number(wallMs.toFixed(1)),
93			receiptBytes: Buffer.byteLength(stdout, 'utf8'),
94			exitCode,
95		};
96	}
97	
98	const timings = [];
99	const queryIndex = {};
100	const prepareMs = Number((Number(process.hrtime.bigint() - started) / 1e6).toFixed(1));
101	
102	for (const symbol of symbols) {
103		const resolveId = `${symbol.id}-q00-resolve-${symbol.name.toLowerCase()}`;
104		const resolved = runQuery(resolveId, {
105			kind: 'resolveBinding',
106			file: symbol.file,
107			name: symbol.name,
108			space: 'value',
109			scope: null,
110		});
111		const anchors = resolved.receipt.results ?? [];
112		if (anchors.length !== 1) {
113			throw new Error(`${resolveId}: expected exactly 1 anchor, got ${anchors.length}`);
114		}
115		const refsId = `${symbol.id}-q01-refs-${symbol.name.toLowerCase()}`;
116		const refs = runQuery(refsId, { kind: 'referencesOf', target: anchors[0] });
117	
118		for (const run of [resolved, refs]) {
119			timings.push({
120				id: run.id,
121				symbol: symbol.id,
122				inputFiles: inputs.length,
123				query: run.receipt.query,
124				state: run.receipt.state,
125				results: Array.isArray(run.receipt.results) ? run.receipt.results.length : null,
126				unresolved: Array.isArray(run.receipt.unresolved) ? run.receipt.unresolved.length : null,
127				wallMs: run.wallMs,
128				receiptBytes: run.receiptBytes,
129				snapshot: run.receipt.snapshot ?? null,
130				exitCode: run.exitCode,
131			});
132			queryIndex[run.id] = {
133				symbol: symbol.id,
134				inputFiles: inputs.length,
135				inputList: 'input-files.txt',
136				corpus: { repo: MARKLESS, commit: head, bytes: corpusBytes },
137				request: run.request,
138				snapshot: run.receipt.snapshot ?? null,
139				state: run.receipt.state,
140			};
141		}
142	}
143	
144	const totalQueryMs = timings.reduce((n, t) => n + t.wallMs, 0);
145	const totalWallMs = Number((Number(process.hrtime.bigint() - started) / 1e6).toFixed(1));
146	
147	writeFileSync(join(HERE, 'query-index.json'), `${JSON.stringify(queryIndex, null, 1)}\n`);
148	writeFileSync(
149		join(HERE, 'timings.json'),
150		`${JSON.stringify(
151			{
152				corpus: { repo: MARKLESS, commit: head, inputFiles: inputs.length, bytes: corpusBytes },
153				queries: timings,
154				prepareMs,
155				totalQueryMs: Number(totalQueryMs.toFixed(1)),
156				totalWallMs,
157				budgetMs: 10 * 60 * 1000,
158			},
159			null,
160			2,
161		)}\n`,
162	);
163	rmSync(scratch, { recursive: true, force: true });
164	console.table(timings.map((t) => ({ id: t.id, state: t.state, results: t.results, unresolved: t.unresolved, wallMs: t.wallMs })));
165	console.log(`total query wall: ${(totalQueryMs / 1000).toFixed(1)}s`);
166

