1	import { canonicalize, sha256 } from './canonicalize.ts';
2	
3	export const UNRESOLVED_REASONS = [
4		'unparsed-file',
5		'unsupported-language',
6		'unsupported-syntax',
7		'unresolved-specifier',
8		'external-module-boundary',
9		'builtin-module-boundary',
10		'linked-set-boundary',
11		'unresolved-symbol',
12		'ambiguous-definition',
13		'dynamic-member-access',
14		'computed-property-key',
15		'string-keyed-lookup',
16		'property-alias-write-uncertain',
17		'higher-order-call-boundary',
18		'stale-snapshot',
19		// A supplied input whose own import/re-export specifier failed to link to
20		// another supplied input: the file could not be established as part of the
21		// traversed graph, so no traversal answer may claim to have covered it.
22		'unlinked-input',
23		// A call whose callee is a member of the queried binding *itself*
24		// ('records.push(...)'): structural analysis proves the receiver is the
25		// binding and proves nothing about the callee's body, so whether the call
26		// mutates the referenced value is unknown. Neither a write may be claimed
27		// nor completeness of writes. The receiver test is strict — in
28		// 'Object.values(x).includes(v)' the receiver of '.includes' is the fresh
29		// array the call returned, not 'x', so that site is not this reason (the
30		// argument position of 'Object.values' is 'argument-escape-mutation-uncertain'
31		// instead). Distinct from 'property-alias-write-uncertain', which names an
32		// *observed* mutation that cannot be attributed to the queried symbol
33		// through an alias.
34		'method-call-mutation-uncertain',
35		// The queried binding is passed as an *argument* to a call
36		// ('encodeSlot(item, path, seen, records, diagnostics)'): the reference
37		// escapes to a callee whose body this analysis does not read for mutation,
38		// so the callee may mutate the referenced value and no structural evidence
39		// can rule it out. The escape is named rather than claimed — an argument is
40		// syntactically a read of the binding, and 'writesOf' filters reads out of
41		// its results, so without this reason the site would vanish from the answer
42		// entirely and 'complete' would be asserted over an invisible mutation.
43		//
44		// Three-way distinction, all about *different* unknowns:
45		//   - 'method-call-mutation-uncertain' — the binding is the RECEIVER of the
46		//     call ('x.sort()'); this reason — the binding is an ARGUMENT of the
47		//     call ('sort(x)'). Receiver versus argument, never both for one site.
48		//   - 'higher-order-call-boundary' — an unknown about *control* flow: which
49		//     function a call actually invokes (an opaque returned callee, an
50		//     invoked parameter, a callback handed to an opaque callee). This
51		//     reason is an unknown about *data*: the callee is named and reachable,
52		//     but what it does to the value it received is not modelled.
53		'argument-escape-mutation-uncertain',
54		// An export-like construct outside the ES module system: a CommonJS
55		// 'module.exports' / 'exports' assignment, an alias of either object, or a
56		// TS 'export ='. The ES export analysis cannot classify it, so the names it
57		// exports are unknown; the construct is named instead of being omitted, so
58		// "exports nothing" is never confused with "exports invisibly".
59		'unrecognized-export-form',
60	] as const;
61	
62	export type UnresolvedReason = (typeof UNRESOLVED_REASONS)[number];
63	
64	export interface SymbolAnchor {
65		readonly schema: 'guessless.symbol-anchor/v1';
66		readonly file: string;
67		readonly semanticPath: readonly string[];
68		readonly fingerprint: string;
69	}
70	
71	export interface UnresolvedSite {
72		readonly site: SymbolAnchor;
73		readonly reason: UnresolvedReason;
74		readonly detail: string;
75	}
76	
77	export const SAFE_CHANGE_ROLES = [
78		'declaration',
79		'reference',
80		'read',
81		'write',
82		'read-write',
83		'call',
84		'import',
85		'export',
86		'alias',
87		'namespace',
88		'barrel',
89		'witness',
90	] as const;
91	
92	export type SafeChangeRole = (typeof SAFE_CHANGE_ROLES)[number];
93	export type SafeChangeIntent = 'rename' | 'delete' | 'entry-point';
94	export interface SafeChangeBindingSelector {
95		readonly file: string;
96		readonly name: string;
97		readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
98		readonly from?: SymbolAnchor;
99	}
100	export type SafeChangeTarget = SymbolAnchor | SafeChangeBindingSelector;
101	
102	export interface SafeChangeImpactResult {
103		readonly site: SymbolAnchor;
104		readonly roles: readonly SafeChangeRole[];
105		readonly witness: readonly SymbolAnchor[];
106	}
107	
108	export type QueryRequest =
109		| { readonly kind: 'addFile'; readonly file: string }
110		| {
111				readonly kind:
112					| 'definitionOf'
113					| 'referencesOf'
114					| 'readsOf'
115					| 'writesOf'
116					| 'capturesOf'
117					| 'reachableFrom'
118					| 'reaches';
119				readonly target: SymbolAnchor;
120		  }
121		| { readonly kind: 'exportedNames'; readonly file: string }
122		| {
123				readonly kind: 'resolveBinding';
124				readonly file: string;
125				readonly name: string;
126				readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
127				readonly scope: SymbolAnchor | null;
128		  }
129		| {
130				readonly kind: 'safeChangeImpact';
131				readonly snapshot: string;
132				readonly intent: SafeChangeIntent;
133				readonly target: SafeChangeTarget;
134		  };
135	
136	interface ReceiptBase<T> {
137		readonly schema: 'guessless.receipt/v1';
138		readonly query: string;
139		readonly request: QueryRequest;
140		readonly snapshot: string;
141		readonly results: readonly T[];
142		readonly integrity: string;
143	}
144	
145	export interface CompleteReceipt<T> extends ReceiptBase<T> {
146		readonly state: 'complete';
147	}
148	export interface PartialReceipt<T> extends ReceiptBase<T> {
149		readonly state: 'partial';
150		readonly unresolved: readonly UnresolvedSite[];
151	}
152	export interface RefusedReceipt<T> extends ReceiptBase<T> {
153		readonly state: 'refused';
154		readonly reason: UnresolvedReason;
155		readonly detail: string;
156	}
157	export type Receipt<T> = CompleteReceipt<T> | PartialReceipt<T> | RefusedReceipt<T>;
158	type WithoutIntegrity<T> = T extends unknown ? Omit<T, 'integrity'> : never;
159	type UnsignedReceipt<T> = WithoutIntegrity<Receipt<T>>;
160	
161	const baseKeys = ['query', 'request', 'results', 'schema', 'snapshot', 'state'] as const;
162	const anchorKeys = ['file', 'fingerprint', 'schema', 'semanticPath'] as const;
163	
164	export function makeReceipt<T>(receipt: UnsignedReceipt<T>): Receipt<T> {
165		assertReceiptShape(receipt);
166		return { ...receipt, integrity: sha256(receipt) } as Receipt<T>;
167	}
168	
169	export function verifyReceipt(value: unknown, currentSnapshot?: string): value is Receipt<unknown> {
170		try {
171			assertReceiptShape(value);
172			const record = value as Record<string, unknown>;
173			if (typeof record.integrity !== 'string' || !/^[a-f0-9]{64}$/.test(record.integrity))
174				return false;
175			if (currentSnapshot !== undefined && record.snapshot !== currentSnapshot) return false;
176			const { integrity, ...unsigned } = record;
177			return integrity === sha256(unsigned);
178		} catch {
179			return false;
180		}
181	}
182	
183	function exactKeys(record: Record<string, unknown>, extras: readonly string[]): void {
184		const expected = [
185			...baseKeys,
186			...extras,
187			...('integrity' in record ? ['integrity'] : []),
188		].sort();
189		const actual = Object.keys(record).sort();
190		if (actual.join('\u0000') !== expected.join('\u0000'))
191			throw new TypeError('receipt state has invalid or cross-state fields');
192	}
193	
194	function assertReceiptShape(value: unknown): void {
195		if (!isRecord(value) || Array.isArray(value))
196			throw new TypeError('receipt must be an object, never a bare list');
197		const record = value;
198		if (
199			record.schema !== 'guessless.receipt/v1' ||
200			typeof record.query !== 'string' ||
201			!Array.isArray(record.results) ||
202			typeof record.snapshot !== 'string' ||
203			!/^[a-f0-9]{64}$/.test(record.snapshot)
204		)
205			throw new TypeError('invalid receipt envelope');
206		assertRequest(record.query, record.request);
207		if (record.state === 'complete') exactKeys(record, []);
208		else if (record.state === 'partial') {
209			exactKeys(record, ['unresolved']);
210			if (!Array.isArray(record.unresolved) || record.unresolved.length === 0)
211				throw new TypeError('partial receipt needs unresolved sites');
212			for (const item of record.unresolved) assertUnresolved(item);
213		} else if (record.state === 'refused') {
214			exactKeys(record, ['detail', 'reason']);
215			if (
216				record.results.length !== 0 ||
217				!isReason(record.reason) ||
218				typeof record.detail !== 'string'
219			)
220				throw new TypeError('invalid refused receipt');
221		} else throw new TypeError('receipt state must be complete, partial, or refused');
222		assertQueryResults(record.query, record.results);
223	}
224	
225	function assertRequest(query: string, value: unknown): asserts value is QueryRequest {
226		if (!isRecord(value) || value.kind !== query)
227			throw new TypeError('receipt request must match query');
228		if (query === 'addFile' || query === 'exportedNames') {
229			if (!hasExactKeys(value, ['file', 'kind']) || typeof value.file !== 'string')
230				throw new TypeError(`invalid ${query} request`);
231			return;
232		}
233		if (
234			[
235				'definitionOf',
236				'referencesOf',
237				'readsOf',
238				'writesOf',
239				'capturesOf',
240				'reachableFrom',
241				'reaches',
242			].includes(query)
243		) {
244			if (!hasExactKeys(value, ['kind', 'target']) || !isAnchor(value.target))
245				throw new TypeError(`invalid ${query} request`);
246			return;
247		}
248		if (query === 'resolveBinding') {
249			if (
250				!hasExactKeys(value, ['file', 'kind', 'name', 'scope', 'space']) ||
251				typeof value.file !== 'string' ||
252				typeof value.name !== 'string' ||
253				!['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) ||
254				(value.scope !== null && !isAnchor(value.scope))
255			)
256				throw new TypeError('invalid resolveBinding request');
257			return;
258		}
259		if (query === 'safeChangeImpact') {
260			if (
261				!hasExactKeys(value, ['intent', 'kind', 'snapshot', 'target']) ||
262				typeof value.snapshot !== 'string' ||
263				!/^[a-f0-9]{64}$/.test(value.snapshot) ||
264				!['rename', 'delete', 'entry-point'].includes(String(value.intent)) ||
265				(!isAnchor(value.target) && !isSafeChangeBindingSelector(value.target))
266			)
267				throw new TypeError('invalid safeChangeImpact request');
268			return;
269		}
270		throw new TypeError(`unknown receipt query '${query}'`);
271	}
272	
273	function assertQueryResults(query: string, results: unknown[]): void {
274		if (query === 'addFile') {
275			if (results.length !== 0) throw new TypeError('addFile refusal cannot have results');
276			return;
277		}
278		if (query === 'definitionOf' || query === 'resolveBinding') {
279			if (results.length > 1 || !results.every(isAnchor))
280				throw new TypeError(`${query} requires at most one anchor result`);
281			return;
282		}
283		if (query === 'referencesOf' || query === 'readsOf' || query === 'writesOf') {
284			for (const result of results) {
285				if (
286					!isRecord(result) ||
287					!hasExactKeys(result, ['access', 'site']) ||
288					!isAnchor(result.site) ||
289					!['read', 'write', 'read-write'].includes(String(result.access))
290				)
291					throw new TypeError('invalid reference result');
292				if (query === 'readsOf' && result.access === 'write')
293					throw new TypeError('readsOf contains a write-only result');
294				if (query === 'writesOf' && result.access === 'read')
295					throw new TypeError('writesOf contains a read-only result');
296			}
297			return;
298		}
299		if (query === 'exportedNames') {
300			for (const result of results)
301				if (
302					!isRecord(result) ||
303					!hasExactKeys(result, ['module', 'name']) ||
304					!isAnchor(result.module) ||
305					typeof result.name !== 'string'
306				)
307					throw new TypeError('invalid export result');
308			return;
309		}
310		if (query === 'capturesOf') {
311			for (const result of results)
312				if (
313					!isRecord(result) ||
314					!hasExactKeys(result, ['isWritten', 'references', 'symbol']) ||
315					!isAnchor(result.symbol) ||
316					!Array.isArray(result.references) ||
317					!result.references.every(isAnchor) ||
318					typeof result.isWritten !== 'boolean'
319				)
320					throw new TypeError('invalid capture result');
321			return;
322		}
323		if (query === 'reachableFrom' || query === 'reaches') {
324			const symbols = new Set<string>();
325			for (const result of results) {
326				if (
327					!isRecord(result) ||
328					!hasExactKeys(result, ['symbol', 'witness']) ||
329					!isAnchor(result.symbol) ||
330					!Array.isArray(result.witness) ||
331					result.witness.length === 0 ||
332					!result.witness.every(isAnchor)
333				)
334					throw new TypeError('invalid reachability result');
335				const identity = canonicalize(result.symbol);
336				if (symbols.has(identity)) throw new TypeError('duplicate reachability result');
337				symbols.add(identity);
338			}
339			return;
340		}
341		if (query === 'safeChangeImpact') {
342			const sites = new Set<string>();
343			for (const result of results) {
344				if (
345					!isRecord(result) ||
346					!hasExactKeys(result, ['roles', 'site', 'witness']) ||
347					!isAnchor(result.site) ||
348					!Array.isArray(result.roles) ||
349					result.roles.length === 0 ||
350					!result.roles.every(isSafeChangeRole) ||
351					new Set(result.roles).size !== result.roles.length ||
352					!Array.isArray(result.witness) ||
353					!result.witness.every(isAnchor)
354				)
355					throw new TypeError('invalid safe-change impact result');
356				const identity = canonicalize(result.site);
357				if (sites.has(identity)) throw new TypeError('duplicate safe-change impact site');
358				sites.add(identity);
359			}
360			return;
361		}
362		throw new TypeError(`unknown receipt query '${query}'`);
363	}
364	
365	function assertUnresolved(value: unknown): void {
366		if (
367			!isRecord(value) ||
368			!hasExactKeys(value, ['detail', 'reason', 'site']) ||
369			!isAnchor(value.site) ||
370			!isReason(value.reason) ||
371			typeof value.detail !== 'string'
372		)
373			throw new TypeError('invalid unresolved site');
374	}
375	function isReason(value: unknown): value is UnresolvedReason {
376		return typeof value === 'string' && (UNRESOLVED_REASONS as readonly string[]).includes(value);
377	}
378	function isSafeChangeRole(value: unknown): value is SafeChangeRole {
379		return typeof value === 'string' && (SAFE_CHANGE_ROLES as readonly string[]).includes(value);
380	}
381	function isSafeChangeBindingSelector(value: unknown): value is SafeChangeBindingSelector {
382		if (!isRecord(value)) return false;
383		const keys =
384			value.from === undefined ? ['file', 'name', 'space'] : ['file', 'from', 'name', 'space'];
385		return (
386			hasExactKeys(value, keys) &&
387			typeof value.file === 'string' &&
388			typeof value.name === 'string' &&
389			['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) &&
390			(value.from === undefined || isAnchor(value.from))
391		);
392	}
393	function isRecord(value: unknown): value is Record<string, unknown> {
394		return value !== null && typeof value === 'object' && !Array.isArray(value);
395	}
396	function hasExactKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
397		return Object.keys(record).sort().join('\u0000') === [...keys].sort().join('\u0000');
398	}
399	
400	export function isAnchor(value: unknown): value is SymbolAnchor {
401		if (!isRecord(value) || !hasExactKeys(value, anchorKeys)) return false;
402		return (
403			value.schema === 'guessless.symbol-anchor/v1' &&
404			typeof value.file === 'string' &&
405			Array.isArray(value.semanticPath) &&
406			value.semanticPath.length > 0 &&
407			value.semanticPath.every((part) => typeof part === 'string') &&
408			typeof value.fingerprint === 'string' &&
409			/^[a-f0-9]{64}$/.test(value.fingerprint)
410		);
411	}
412	
