	const withoutLoaders = specifier.slice(specifier.lastIndexOf('!') + 1);
	const withoutQuery = withoutLoaders.split('?')[0]?.split('#')[0] ?? '';
	return withoutQuery.replace(/\/+$/, '').replace(/^\/+/, '');
